/*
r̄ = v̄×ō
        s̄ = ō×ū
        n̄ = ū×v̄
        `kᵣ` = r̄⋅(`C̄ₐ`-V̄)
        `kₛ` = s̄⋅(`C̄ₐ`-V̄)
        `kₙ` = n̄⋅(`C̄ₐ`-V̄)
        `x(θ,v)` =  (r̄⋅`D_A`(θ, v)+`kᵣ`delta(θ, v))/(n̄⋅`D_A`(θ, v)+`kₙ`delta(θ, v))
        `y(θ,v)` =  (s̄⋅`D_A`(θ, v)+`kₛ`delta(θ, v))/(n̄⋅`D_A`(θ, v)+`kₙ`delta(θ, v))
        where
        v̄: ℝ^3
        ō: ℝ^3
        ū: ℝ^3
        V̄: ℝ^3
        `C̄ₐ`: ℝ^3
        θ: ℝ
        v: ℝ
        `D_A`: ℝ,ℝ->ℝ^3
        `delta`: ℝ,ℝ->ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    Eigen::Matrix<DT, 3, 1> r̄;
    Eigen::Matrix<DT, 3, 1> s̄;
    Eigen::Matrix<DT, 3, 1> n̄;
    DT kᵣ;
    DT kₛ;
    DT kₙ;
    DT xθ_comma_v;
    DT yθ_comma_v;

    heartlib(
        const Eigen::Matrix<double, 3, 1> & v̄,
        const Eigen::Matrix<double, 3, 1> & ō,
        const Eigen::Matrix<double, 3, 1> & ū,
        const Eigen::Matrix<double, 3, 1> & V̄,
        const Eigen::Matrix<double, 3, 1> & C_combining_macron_ₐ,
        const double & θ,
        const double & v,
        const std::function<Eigen::Matrix<double, 3, 1>(double, double)> & D_A,
        const std::function<double(double, double)> & delta)
    {

        // r̄ = v̄×ō
        r̄ = (v̄).cross(ō);
        // s̄ = ō×ū
        s̄ = (ō).cross(ū);
        // n̄ = ū×v̄
        n̄ = (ū).cross(v̄);
        // `kᵣ` = r̄⋅(`C̄ₐ`-V̄)
        kᵣ = (r̄).dot((C_combining_macron_ₐ - V̄));
        // `kₛ` = s̄⋅(`C̄ₐ`-V̄)
        kₛ = (s̄).dot((C_combining_macron_ₐ - V̄));
        // `kₙ` = n̄⋅(`C̄ₐ`-V̄)
        kₙ = (n̄).dot((C_combining_macron_ₐ - V̄));
        // `x(θ,v)` =  (r̄⋅`D_A`(θ, v)+`kᵣ`delta(θ, v))/(n̄⋅`D_A`(θ, v)+`kₙ`delta(θ, v))
        xθ_comma_v = ((r̄).dot(D_A(θ, v)) + kᵣ * delta(θ, v)) / DT(((n̄).dot(D_A(θ, v)) + kₙ * delta(θ, v)));
        // `y(θ,v)` =  (s̄⋅`D_A`(θ, v)+`kₛ`delta(θ, v))/(n̄⋅`D_A`(θ, v)+`kₙ`delta(θ, v))
        yθ_comma_v = ((s̄).dot(D_A(θ, v)) + kₛ * delta(θ, v)) / DT(((n̄).dot(D_A(θ, v)) + kₙ * delta(θ, v)));
    }
};

